  const paper=getPaper(),sourceReady=paper.scope!=='metadata'&&parts.length>0,result=currentResult(frozen);let step=sourceReady?2:1,phase='prepare',hint=sourceReady?(problem||'核对本次原文范围与处理方式，点击下方按钮即可开始。'):'请先添加正文或明确采用的摘要，再选择研读方式。';
  if(progress.auth==='changed'){step=1;phase='blocked';hint='账户状态已变化，请重新进入本功能后继续。';}
  else if(settingsChanged&&!progress.submitting){step=sourceReady?2:1;phase='review';hint='处理设置或原文范围已更新，下方保留的是之前的任务与结果；可按当前设置重新处理。';}
  else if(progress.submitting||progress.busy||['queued','running'].includes(progress.status)){step=frozen?3:sourceReady?2:1;phase=progress.status==='queued'?'queued':progress.status==='running'?'running':'preparing';hint=step===3?(phase==='queued'?'任务已提交，正在等待处理；进度会自动更新。':phase==='running'?'正在处理本次原文，具体状态在下方任务区更新。':'正在核对本次资料并准备任务，请稍候，无需重复提交。'):'正在核对本次原文与处理设置。';}
  else if(progress.hasError||['failed','cancelled'].includes(progress.status)){step=progress.hasTask?3:sourceReady?2:1;phase=progress.status==='cancelled'?'cancelled':'failed';hint=phase==='cancelled'?'本次处理已停止，原文和已保存结果仍保留。':'本次尚未完成，请查看下方具体原因；原文和已保存结果仍保留。';}
  else if(result){step=4;phase='complete';hint=operation==='translate'?'对照译文已保存，可核对原文与术语，再导出结果。':operation==='answer'?'回答与原文依据已保存，可逐项核对并导出。':'研读结果与原文依据已保存，可继续核对、修改和导出。';}
  else if(progress.status==='completed'){step=3;phase='result_unavailable';hint='任务已结束，结果仍待核对与保存，请查看下方任务区。';}
