 function bindResults(){container.querySelectorAll('[data-lit-ai-save]').forEach(button=>button.onclick=()=>{if(flushPendingEdits())ctx.notify?.('修改已保存到当前浏览器，原文依据保留。');});container.querySelectorAll('[data-document-export]').forEach(button=>button.addEventListener('click',event=>{if(!flushPendingEdits()){event.preventDefault();event.stopImmediatePropagation();const status=container.ownerDocument.getElementById(button.id.replace(/-(?:docx|pdf)$/,'')+'-status');if(status)status.textContent='当前修改尚未保存，已停止导出旧内容。请先重试保存或复制当前修改。';}},{capture:true}));container.querySelectorAll('[data-lit-ai-remove]').forEach(button=>button.onclick=()=>{if(!win.confirm('仅移除此浏览器中的研读或翻译结果。原文、笔记与账户任务保留；请先导出需要保留的内容。确认移除？'))return;try{updatePaper(p=>({...p,aiResults:(p.aiResults||[]).filter(result=>result.id!==button.dataset.litAiRemove)}));for(const [key,row] of pendingEdits)if(row.resultId===button.dataset.litAiRemove)pendingEdits.delete(key);render();ctx.notify?.('本地结果已移除，原文与账户任务仍保留。');}catch(error){ctx.notify?.(error.message||'移除失败，原结果仍保留。');}});container.querySelectorAll('[data-lit-ai-result][data-lit-ai-text],[data-lit-ai-result][data-lit-ai-segment]').forEach(editor=>editor.oninput=()=>{const row={resultId:editor.dataset.litAiResult,segmentId:editor.dataset.litAiSegment||'',text:editor.value};pendingEdits.set(JSON.stringify([row.resultId,row.segmentId]),row);flushPendingEdits();});if(pendingEdits.size)showPendingStatus(pendingError||'当前修改尚未保存，请重试保存或复制备份。');for(const result of getPaper().aiResults||[])bindDocumentExports('lit-ai-'+result.id,()=>exportResult(result.id),()=>getPaper().title+'-'+names[result.operation],container.ownerDocument.getElementById('lit-ai-'+result.id+'-status'));container.querySelectorAll('[data-lit-ai-export]').forEach(button=>button.onclick=async()=>{try{const paper=getPaper(),result=(paper.aiResults||[]).find(r=>r.id===button.dataset.litAiExport);if(result){await download(paper.title+'-'+names[result.operation]+'.txt',exportResult(result.id));ctx.notify?.('已发起下载，原文依据与译文对应关系一并导出。');}}catch(error){ctx.notify?.(error.message);}});container.querySelectorAll('[data-lit-source]').forEach(link=>link.onclick=e=>{e.preventDefault();const paper=getPaper(),result=(paper.aiResults||[]).find(r=>r.id===link.dataset.litResult),frozen=result?.materials?.find(m=>m.id===link.dataset.litSource),actual=literatureParagraphs(paper.text).find(p=>p.id===link.dataset.litSource);const source=container.ownerDocument.getElementById('lit-source-'+link.dataset.litSource);if(!source||actual?.text!==frozen?.text){ctx.notify?.('原文已修改，请以本次结果导出的原文依据为准。');return;}const textPane=container.ownerDocument.getElementById('reader-text-pane'),notesPane=container.ownerDocument.getElementById('reader-notes-pane');if(textPane)textPane.hidden=false;if(notesPane)notesPane.hidden=true;container.ownerDocument.querySelectorAll('[data-read-tab]').forEach(b=>b.classList.toggle('active',b.dataset.readTab==='text'));source.scrollIntoView({behavior:'smooth',block:'center'});source.classList.add('lit-ai-source-highlight');win.setTimeout(()=>source.classList.remove('lit-ai-source-highlight'),3000);});}
 render();return {dispose(){live=false;panel?.dispose();},getState:()=>({...draft}),getPendingEdits,flushPendingEdits};
